export type Post = {
  id: string
  title: string
  content: string
  createdAt: string
}

const posts: Post[] = [
  {
    id: '1',
    title: 'Welcome',
    content: 'This is the first post. Create another below.',
    createdAt: new Date().toISOString(),
  },
]

export function getAllPosts(): Post[] {
  return [...posts].sort((a, b) => b.createdAt.localeCompare(a.createdAt))
}

export function createPostInStore(input: {
  title: string
  content: string
}): Post {
  const post: Post = {
    id: crypto.randomUUID(),
    title: input.title,
    content: input.content,
    createdAt: new Date().toISOString(),
  }
  posts.unshift(post)
  return post
}

