import { unstable_cache } from 'next/cache'
import { getAllPosts } from '@/lib/posts-store'

/**
 * Posts list is cached under the "posts" tag so it can be invalidated after mutations.
 */
export const getCachedPosts = unstable_cache(
  async () => getAllPosts(),
  ['posts-list'],
  { tags: ['posts'] }
)

