'use server'

import { updateTag } from 'next/cache'
import { redirect } from 'next/navigation'
import { createPostInStore } from '@/lib/posts-store'

export async function createPost(formData: FormData) {
  const title = String(formData.get('title') ?? '').trim()
  const content = String(formData.get('content') ?? '').trim()

  if (!title || !content) {
    return
  }

  createPostInStore({ title, content })

  /**
   * Expires cached entries for this tag so the following navigation/RSC request
   * blocks until fresh data is computed — no stale-while-revalidate for this tag.
   */
  updateTag('posts')

  redirect('/')
}

